<?php
/**
 * Compatibility-preserving controller action seam. The ePaper front controller
 * retains route dispatch; actions are composed into it until typed controllers
 * can be introduced behind the same route contract.
 */
namespace EpaperSaas\Controllers;
use EpaperSaas\Core\{Auth,Build,Config,Http,RateLimiter,RedisStore,RequestContext,Store,Uuid,View};
use EpaperSaas\Services\{AnalyticsCatalog,Audit,CacheInspector,ClipService,DomainResolver,DirectRecovery,EditionOperations,EditionManifest,Entitlements,InfrastructureConfig,Media,DesktopAuth,DeviceAuth,MobileAuth,MobileAuthPendingException,MultiLayerCache,OfflineVault,PlatformClient,Processing,ProcessingRecovery,ProductionReadiness,PublicReadCache,PublishingRuntime,PublishingScheduler,QueueService,RecoveryCenter,RabbitMq,ReaderNavigation,ReaderSession,RuntimeCache,SchemaDoctor,SemanticNews,SeoDiscovery,SettingsCatalog,SupervisorRuntime,TenantData,TrustedAppAuth,PerformanceTelemetry};

trait OperationsActions
{
    private function adminProcessingRepairQueue(): never
    {
        Auth::requireInfrastructureAdmin();if(!RateLimiter::allow('queue-repair:'.RequestContext::tenantGuid(),3,300))$this->adminError('Queue repair is temporarily rate-limited');
        $result=QueueService::repairQueueBacklog();Audit::log('queue.dispatch.safe_repair','tenant',RequestContext::tenantGuid(),'SUCCESS',$result);Http::redirect('/admin/system/recovery?repaired=1');
    }

    private function processingRows(): array
    {
        $editions=Store::all('SELECT DISTINCT e.edition_guid,e.edition_date,e.status,p.name publication_name,MAX(j.updated_at) last_activity FROM ep_editions e JOIN ep_processing_jobs j ON j.tenant_guid=e.tenant_guid AND j.edition_guid=e.edition_guid LEFT JOIN ep_publications p ON p.tenant_guid=e.tenant_guid AND p.publication_guid=e.publication_guid WHERE e.tenant_guid=? GROUP BY e.edition_guid,e.edition_date,e.status,p.name ORDER BY last_activity DESC LIMIT 50',[TenantData::tenantBin()]);
        $out=[];foreach($editions as$e){$editionGuid=$this->guid($e['edition_guid']);$p=QueueService::editionProgress($editionGuid);$all=$p['rows'];$status=(string)$e['status'];if(array_filter($all,fn($r)=>$r['status']==='RUNNING'))$status='RUNNING';elseif(array_filter($all,fn($r)=>$r['status']==='RETRY_WAIT'))$status='RETRY_WAIT';elseif(array_filter($all,fn($r)=>$r['status']==='QUEUED'))$status='QUEUED';elseif($status==='NEEDS_ATTENTION')$status='NEEDS_ATTENTION';elseif($status==='READY')$status='READY';$errors=array_values(array_filter(array_map(fn($r)=>trim((string)($r['error_message']??'')),$all)));$latest='';$attempt=1;foreach($all as$r){if((string)$r['updated_at']>$latest)$latest=(string)$r['updated_at'];$attempt=max($attempt,(int)$r['attempt_count']);}$stage='Render '.$p['render']['completed'].'/'.$p['render']['total'].' · Assets '.$p['assets']['completed'].'/'.$p['assets']['total'].' · OCR '.$p['ocr']['completed'].'/'.$p['ocr']['total'];if($p['ocr']['retry']||$p['assets']['retry'])$stage.=' · Retry '.($p['ocr']['retry']+$p['assets']['retry']);$stale=(bool)array_filter($all,fn($r)=>in_array($r['status'],['QUEUED','RUNNING','RETRY_WAIT'],true)&&(int)($r['age_seconds']??0)>EditionOperations::STALE_SECONDS);$out[]=['job_guid'=>$editionGuid,'edition_guid'=>$editionGuid,'edition'=>trim((string)$e['publication_name'].' '.(string)$e['edition_date']),'status'=>$status,'progress'=>$p['overall'],'stage'=>'PIPELINE','page'=>0,'total_pages'=>0,'message'=>$stage,'updated_at'=>$latest?:$e['last_activity'],'error'=>$errors?implode(' | ',array_slice(array_unique($errors),0,2)):'','stale'=>$stale,'attempt_count'=>$attempt];}return$out;
    }

    private function processingRowsHtml(array $rows): string
    {
        if(!$rows)return '<tr><td colspan="6"><div class="empty-inline">No processing jobs yet.</div></td></tr>';
        $h='';foreach($rows as$d){$pct=max(0,min(100,(float)$d['progress']));$action='';if(in_array($d['status'],['FAILED','NEEDS_ATTENTION'],true)||$d['stale'])$action='<form class="inline" method="post" action="/admin/editions/'.$this->e($d['edition_guid']).'/'.($d['stale']?'recover':'reprocess').'">'.$this->csrf().'<button class="console-icon-action is-process" title="'.($d['stale']?'Recover unfinished work':'Retry processing').'" aria-label="'.($d['stale']?'Recover unfinished work':'Retry processing').'">'.View::icon('refresh').'</button></form>';$err=$d['error']?'<span class="processing-error">'.$this->e($d['error']).'</span> ':'';$h.='<tr data-job-guid="'.$this->e($d['job_guid']).'"><td><a class="text-link" href="/admin/processing/'.$this->e($d['edition_guid']).'">'.$this->e($d['edition']).'</a></td><td><span class="status '.strtolower($d['status']).'">'.$this->e($d['status']).'</span>'.($d['stale']?' <span class="pill warning">STALE</span>':'').'</td><td><div class="processing-progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="'.$pct.'"><span style="width:'.$pct.'%"></span></div><div class="processing-progress-meta"><strong>'.number_format($pct,2).'%</strong><span>Attempt '.max(1,$d['attempt_count']).'</span></div></td><td>'.$this->e($d['message']?:'Waiting').'</td><td><time>'.$this->e($d['updated_at']).'</time></td><td>'.$err.$action.'</td></tr>';}
        return$h;
    }

    private function adminAccess(): never
    {
        $m=Auth::currentMembership();$u=Auth::user();$h='<section class="admin-head"><div><span class="eyebrow">ACCESS</span><h1>Roles & access</h1><p class="muted">Identity and memberships are authoritative in Digiti Platform; ePaper SaaS enforces the active tenant membership on every admin request.</p></div></section><div class="two-col"><section class="panel"><h2>Current administrator</h2><dl class="detail-list"><div><dt>Name</dt><dd>'.$this->e($u['display_name']??'').'</dd></div><div><dt>Email</dt><dd>'.$this->e($u['email']??'').'</dd></div><div><dt>Role</dt><dd>'.$this->e($m['role_key']??'').'</dd></div><div><dt>Tenant</dt><dd><code>'.$this->e(RequestContext::tenantGuid()).'</code></dd></div></dl></section><section class="panel"><h2>Security boundary</h2><ul class="check-list"><li>Host-resolved Product Tenant</li><li>Platform identity verification</li><li>Tenant membership enforcement</li><li>Server-side RBAC</li><li>Tenant-scoped repositories</li><li>Audited administration</li></ul><p class="muted">Add/remove users and memberships from Digiti Platform. No cross-tenant membership is inferred from browser input.</p></section></div>';View::layout('Roles & access',$h,['brand'=>$this->brandName(),'admin'=>true]);
    }

    private function adminStorage(): never
    {
        $root=dirname(__DIR__,2);$storage=$root.'/storage';$paths=['Original uploads'=>$storage.'/uploads','Generated editions'=>$storage.'/editions','Encrypted/offline metadata'=>$storage.'/offline','Clips'=>$storage.'/clips','Runtime cache'=>$storage.'/cache','Logs'=>$storage.'/logs'];$cards='';
        foreach($paths as$name=>$path){$bytes=$this->dirSize($path);$cards.='<div class="health-card"><span>'.$this->e($name).'</span><strong>'.$this->e($this->formatBytes($bytes)).'</strong><small>'.(is_dir($path)?(is_writable($path)?'Writable':'Read only'):'Not created yet').'</small></div>';}
        $free=@disk_free_space($root);$total=@disk_total_space($root);$pct=($free!==false&&$total&&$total>0)?round(($free/$total)*100,1):null;$diskTone=$pct!==null&&$pct<8?'danger':($pct!==null&&$pct<15?'warning':'success');
        $oldTmp=0;$oldTmpBytes=0;$tmpScanned=0;$tmpScanLimit=5000;$tmpScanTruncated=false;$cut=time()-86400;if(is_dir($storage)){try{$it=new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($storage,\FilesystemIterator::SKIP_DOTS));foreach($it as$f){if(!$f->isFile())continue;if(++$tmpScanned>$tmpScanLimit){$tmpScanTruncated=true;break;}if($f->getMTime()>=$cut)continue;$n=$f->getFilename();if(str_contains($n,'.tmp')||str_ends_with($n,'.part')||str_contains($n,'.tmp.')){$oldTmp++;$oldTmpBytes+=(int)$f->getSize();}}}catch(\Throwable){}}
        $h='<section class="admin-head"><div><span class="eyebrow">OPERATIONS & RECOVERY</span><h1>Storage & backups</h1><p class="muted">Disk pressure, application storage growth and the external backup responsibilities required before a production release.</p></div><a class="btn ghost" href="/admin/system/health">Production readiness</a></section>';
        $h.='<div class="alert '.$diskTone.'"><strong>Disk capacity</strong><p>'.($pct===null?'Filesystem capacity could not be measured.':$this->e($this->formatBytes((int)$free)).' free of '.$this->e($this->formatBytes((int)$total)).' · '.$pct.'% available.').'</p></div><div class="health-grid">'.$cards.'</div>';
        $h.='<div class="two-col"><section class="panel"><div class="section-head"><div><span class="eyebrow">HYGIENE</span><h2>Storage housekeeping</h2></div></div><dl class="detail-list"><div><dt>Stale temp files &gt;24h</dt><dd>'.$oldTmp.'</dd></div><div><dt>Stale temp bytes</dt><dd>'.$this->e($this->formatBytes($oldTmpBytes)).'</dd></div><div><dt>Temp scan</dt><dd>'.($tmpScanTruncated?'Capped at '.number_format($tmpScanned).' files':'Complete · '.number_format($tmpScanned).' files').'</dd></div><div><dt>Supervisor log rotation</dt><dd>20 MB × 5 backups / worker log</dd></div></dl><p class="muted">Cache maintenance removes expired cache/temp lock artifacts; processing source PDFs and active Reader assets are never deleted by generic cache cleanup.</p><a class="btn ghost" href="/admin/performance">Open cache maintenance</a></section>';
        $h.='<section class="panel"><div class="section-head"><div><span class="eyebrow">BACKUP RESPONSIBILITY</span><h2>Cloudways backup & restore</h2></div><span class="status warning">MANUAL VERIFICATION</span></div><p>EP-DI cannot prove the state of Cloudways server backups from local application files. Before v2.0.0 stable, complete an on-demand backup and one documented restore rehearsal.</p><ol><li>Create an on-demand application/database backup.</li><li>Record the backup timestamp and application version.</li><li>Restore to a safe/staging target or rehearse the documented restore procedure.</li><li>Verify MariaDB schema, original PDFs, generated assets, configuration and Supervisor processes.</li><li>Keep the RC rollback ZIP and database backup together.</li></ol><p class="muted">The Production Readiness Center intentionally reports this as <strong>REVIEW</strong> until the operator completes the external acceptance step.</p></section></div>';
        View::layout('Storage & backups',$h,['brand'=>$this->brandName(),'admin'=>true]);
    }

