        $tb=TenantData::tenantBin();$row=Store::one('SELECT
            (SELECT COUNT(*) FROM ep_editions WHERE tenant_guid=? AND status="PUBLISHED") AS published_editions,
            (SELECT COUNT(*) FROM ep_pages WHERE tenant_guid=?) AS pages,
            (SELECT COUNT(*) FROM ep_page_ocr WHERE tenant_guid=? AND status="READY") AS ocr_pages,
            (SELECT COUNT(*) FROM ep_analytics_events WHERE tenant_guid=? AND occurred_at>=DATE_SUB(NOW(),INTERVAL 1 DAY)) AS reader_events_24h',[$tb,$tb,$tb,$tb])?:[];
