        $q=QueueService::rabbitEnabled()?RabbitMq::instance()->queueStats():[];$outbox=QueueService::outboxBacklog();$cache=CacheInspector::snapshot();$perf=PerformanceTelemetry::snapshot();$redis=$cache['redis'];$fs=$cache['fs'];$man=$cache['manifests'];$generations=$cache['generations'];$membership=Auth::currentMembership();$infraRoles=array_map('strtoupper',(array)Config::get('auth.infrastructure_roles',['OWNER','ADMIN']));$canMaintain=$membership&&in_array(strtoupper((string)($membership['role_key']??'')),$infraRoles,true);
