        foreach($cards as[$a,$b,$c])$h.='<div class="health-card"><span>'.$this->e($a).'</span><strong>'.$this->e($b).'</strong><small>'.$this->e($c).'</small></div>';$h.='</div></section>';
        $h.='<div class="two-col"><section class="panel"><div class="section-head"><div><span class="eyebrow">CACHE GENERATIONS</span><h2>Revision pointers</h2><p class="muted">Writes advance generations so public reads switch immediately without synchronously deleting every old key.</p></div></div><div class="detail-list">';foreach($generations as$g=>$v)$h.='<div><dt>'.$this->e($g).'</dt><dd>r'.(int)$v.'</dd></div>';$h.='</div></section><section class="panel"><div class="section-head"><div><span class="eyebrow">SAFE OPERATIONS</span><h2>Cache maintenance</h2><p class="muted">Compiled edition manifests are intentionally separate from generic runtime cache.</p></div></div>';if($canMaintain){$h.='<div class="form-stack"><form method="post" action="/admin/performance/cache-action">'.$this->csrf().'<input type="hidden" name="action" value="purge"><button class="btn ghost" type="submit">Purge application read cache</button><p class="muted">Advances public/settings generations and clears runtime read models. Published manifest revisions remain available.</p></form><form method="post" action="/admin/performance/cache-action">'.$this->csrf().'<input type="hidden" name="action" value="manifests"><button class="btn ghost" type="submit">Rebuild published manifests</button><p class="muted">Regenerates immutable Reader snapshots for recent published editions.</p></form></div>';}else{$h.='<div class="empty-inline">Cache maintenance actions are restricted to infrastructure administrators.</div>';}$h.='</section></div>';
        $h.='<section class="panel"><div class="section-head"><div><span class="eyebrow">QUEUE PRESSURE</span><h2>Publishing lanes</h2><p class="muted">Broker queue depth plus durable transactional-outbox age.</p></div><span class="pill">oldest outbox '.($outbox['oldest_pending_seconds']? $this->e((string)$outbox['oldest_pending_seconds']).' sec':'clear').'</span></div><div class="queue-lanes">';if(!$q)$h.='<div class="empty-inline">Queue telemetry unavailable.</div>';foreach($q as$name=>$st)$h.='<div class="queue-lane"><code>'.$this->e($name).'</code><strong>'.(int)($st['ready']??0).'</strong><span>'.(int)($st['consumers']??0).' consumers</span></div>';$h.='</div><div class="detail-metric-grid performance-outbox"><div class="detail-metric"><span>Outbox pending</span><strong>'.(int)$outbox['pending'].'</strong></div><div class="detail-metric"><span>Outbox failed</span><strong>'.(int)$outbox['failed'].'</strong></div><div class="detail-metric"><span>Oldest pending</span><strong>'.(int)$outbox['oldest_pending_seconds'].'s</strong></div></div></section>';
