ad($r);$profile=(string)($payload['processing_profile']??'default');if((int)($payload['auto_rescue_attempt']??0)>0)$profile='auto recovery '.(int)$payload['auto_rescue_attempt'];$trail='';foreach((array)($payload['trace']??[]) as$event)$trail.='<div><time>'.$this->e($event['at']??'').'</time> '.$this->e($event['event']??'').' · '.$this->e($event['detail']??'').'</div>';$h.='<tr><td><code>'.$this->e($r['job_type']).'</code>'.($trail?'<details><summary>Job trail</summary>'.$trail.'</details>':'').'</td><td><span class="pill">'.$this->e(ucwords(str_replace('_',' ',$profile))).'</span></td><td><span class="status '.strtolower($r['status']).'">'.$this->e($r['status']).'</span></td><td>'.number_format((float)$r['progress'],2).'%</td><td>'.(int)$r['attempt_count'].'</td><td>'.$this->e($r['worker_id']??'').'</td><td>'.$this->e($r['error_message']??'').'</td></tr>';}$h.='</tbody></table></div></div>';View::layout('Processing detail',$h,['brand'=>$this->brandName(),'admin'=>true]);
