        $h='<section class="admin-head"><div><span class="eyebrow">OPERATIONS & RECOVERY</span><h1>Web Recovery Center</h1><p class="muted">Analyze → classify → preview → safe repair. Confirmed broker dispatches are preserved; unknown transport failures are never silently retried.</p></div><div class="page-head-actions"><a class="btn ghost" href="/admin/system/recovery.json" target="_blank" rel="noopener">Recovery JSON</a><a class="btn ghost" href="/admin/system/health">Production readiness</a></div></section>'.$notice;
