    private function adminRecoveryReconcile(): never{Auth::requireInfrastructureAdmin();if((string)($_POST['confirm']??'')!=='1')$this->adminError('Confirm safe outbox reconciliation before applying it.');if(!RateLimiter::allow('recovery-reconcile:'.RequestContext::tenantGuid(),2,300))$this->adminError('Outbox reconciliation is temporarily rate-limited');$r=RecoveryCenter::reconcileOutbox();Audit::log('recovery.outbox.reconcile','tenant',RequestContext::tenantGuid(),'SUCCESS',$r['applied']??$r);Http::redirect('/admin/system/recovery?reconciled=1');}

    private function adminRecoveryRepairMissing(): never{Auth::requireInfrastructureAdmin();if((string)($_POST['confirm']??'')!=='1')$this->adminError('Confirm missing-dispatch repair before applying it.');if(!RateLimiter::allow('recovery-missing:'.RequestContext::tenantGuid(),2,300))$this->adminError('Missing-dispatch repair is temporarily rate-limited');$r=RecoveryCenter::repairMissingDispatches();Audit::log('recovery.dispatch.missing','tenant',RequestContext::tenantGuid(),'SUCCESS',['missing'=>$r['missing']??0,'created'=>$r['created']??0,'skipped'=>$r['skipped']??0]);Http::redirect('/admin/system/recovery?missing=1');}

    private function adminRecoveryRedisBaseline(): never{Auth::requireInfrastructureAdmin();if(!RateLimiter::allow('recovery-redis-baseline:'.RequestContext::tenantGuid(),3,300))$this->adminError('Redis telemetry baseline is temporarily rate-limited');$r=RecoveryCenter::captureRedisBaseline();Audit::log('recovery.redis.baseline','system',null,'SUCCESS',['evicted_keys'=>$r['evicted_keys']??0,'used_memory'=>$r['used_memory']??0,'keys'=>$r['keys']??0]);Http::redirect('/admin/system/recovery?redis=1');}

